import type { EngineInterface, Register } from 'claude-code'

import { classify, type Classification, type CommandFact } from './classify'
import { preview, type PreviewFacts, type PreviewTarget } from './preview'

const hasGlob = (value: string) => /[*?[]/.test(value)
const cannotExpandGlob = (value: string) => value.includes('**') || value.includes('{') || value.includes('}')

const inClass = (source: string, value: string) => {
  for (let index = 0; index < source.length; index += 1) {
    const start = source[index] ?? ''
    const end = source[index + 2]
    if (source[index + 1] === '-' && end !== undefined) {
      if (start <= value && value <= end) return true
      index += 2
    } else if (start === value) return true
  }
  return false
}

const matches = (pattern: string, name: string) => {
  let patternIndex = 0
  let nameIndex = 0
  let starIndex = -1
  let retryNameIndex = 0

  while (nameIndex < name.length) {
    const token = pattern[patternIndex]
    if (token === '*') {
      starIndex = patternIndex
      patternIndex += 1
      retryNameIndex = nameIndex
    } else if (token === '?' || token === name[nameIndex]) {
      patternIndex += 1
      nameIndex += 1
    } else if (token === '[') {
      const close = pattern.indexOf(']', patternIndex + 1)
      if (close !== -1 && inClass(pattern.slice(patternIndex + 1, close), name[nameIndex] ?? '')) {
        patternIndex = close + 1
        nameIndex += 1
      } else if (starIndex !== -1) {
        patternIndex = starIndex + 1
        retryNameIndex += 1
        nameIndex = retryNameIndex
      } else return false
    } else if (starIndex !== -1) {
      patternIndex = starIndex + 1
      retryNameIndex += 1
      nameIndex = retryNameIndex
    } else return false
  }

  while (pattern[patternIndex] === '*') patternIndex += 1
  return patternIndex === pattern.length
}

const globParts = (target: string) => {
  const slash = target.lastIndexOf('/')
  if (slash === -1) return { directory: '.', pattern: target, prefix: '' }
  const directory = slash === 0 ? '/' : target.slice(0, slash)
  return { directory, pattern: target.slice(slash + 1), prefix: target.slice(0, slash + 1) }
}

const tracked = async ($: EngineInterface, path: string) => {
  const result = await $.process.run(['git', 'ls-files', '--error-unmatch', '--', path]).catch(() => undefined)
  return result?.exitCode === 0
}

const expandedTargets = async ($: EngineInterface, target: string): Promise<{ targets: PreviewTarget[]; unexpanded?: string }> => {
  if (!hasGlob(target)) {
    const stat = await $.fs.stat(target).catch(() => undefined)
    if (!stat) return { targets: [{ path: target }] }
    return { targets: [{ path: target, bytes: stat.size, tracked: await tracked($, target) }] }
  }
  if (cannotExpandGlob(target)) return { targets: [], unexpanded: target }

  const { directory, pattern, prefix } = globParts(target)
  const entries = await $.fs.list(directory).catch(() => undefined)
  if (!entries) return { targets: [], unexpanded: target }

  return {
    targets: await Promise.all(entries.flatMap(entry => {
      if (!matches(pattern, entry.name)) return []
      const path = `${prefix}${entry.name}`
      return [(async () => ({ path, bytes: entry.size, tracked: await tracked($, path) }))()]
    })),
  }
}

const dryRun = async ($: EngineInterface, commands: readonly CommandFact[]) => {
  const command = commands.find(item => item.program === 'git' && item.args[0] === 'clean')
  if (command) {
    const result = await $.process.run(['git', 'clean', '-n', ...command.args.slice(1)]).catch(() => undefined)
    if (result) return { label: 'git clean -n', output: result.stdout || result.stderr }
  }

  if (commands.some(item => item.program === 'git' && ['reset', 'checkout', 'restore'].includes(item.args[0] ?? ''))) {
    const result = await $.process.run(['git', 'diff', '--stat']).catch(() => undefined)
    if (result) return { label: 'git diff --stat', output: result.stdout || result.stderr }
  }

  const rsync = commands.find(item => item.program === 'rsync')
  if (rsync) {
    const result = await $.process.run(['rsync', '-n', ...rsync.args]).catch(() => undefined)
    if (result) return { label: 'rsync -n', output: result.stdout || result.stderr }
  }

  return undefined
}

const previewFacts = async ($: EngineInterface, command: string, result: Classification): Promise<PreviewFacts> => {
  const expanded = await Promise.all(result.commands.flatMap(item => item.targets).map(target => expandedTargets($, target)))
  const targets = expanded.flatMap(item => item.targets)
  const totalBytes = targets.reduce((total, target) => total + (target.bytes ?? 0), 0)

  return {
    command,
    reason: result.reason ?? 'this command may have a broad effect',
    targets,
    totalBytes: targets.some(target => target.bytes !== undefined) ? totalBytes : undefined,
    unexpandedGlobs: expanded.flatMap(item => item.unexpanded ? [item.unexpanded] : []),
    dryRun: await dryRun($, result.commands),
  }
}

const refusal = (command: string, reason: string) => `Bash command ${JSON.stringify(command)} was refused by blast-radius: ${reason}.`

let isInteractive = false

export const captureSession = (interactive: boolean) => {
  isInteractive = interactive
}

export const register: Register = on => {
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const result = classify(e.command)
    if (result.tier === 'pass') return next(e)
    if (result.tier === 'deny') return { deny: refusal(e.command, result.reason ?? 'it is unconditionally dangerous') }
    if (!isInteractive) return { deny: refusal(e.command, 'nobody is available to answer the blast-radius prompt') }

    const facts = await previewFacts($, e.command, result).catch(() => ({
      command: e.command,
      reason: result.reason ?? 'this command may have a broad effect',
    }))
    try {
      const answer = await $.ui.ask(`${preview(facts)}\n\nAllow this Bash command?`, ['Allow', 'Deny'])
      return answer === 'Allow'
        ? next(e)
        : { deny: refusal(e.command, 'the blast-radius prompt was not allowed') }
    } catch {
      return { deny: refusal(e.command, 'the blast-radius prompt was dismissed') }
    }
  }).catch(($, e, next) => next.called ? next(e) : { deny: 'Bash command was refused by blast-radius: the guard failed closed.' })
}

files.hooks/clear.tsx:
import {
  atom,
  read,
  update,
  type CommandRunInput,
  type CommandRunResult,
  type EngineInterface,
  type Next,
  type Register,
} from 'claude-code'

import { toRepoInfo, type RepoInfo } from './repo'
import {
  buildDigest,
  extractSavedPath,
  isRealWork,
  parseReply,
  RECENT_SAVE_MS,
  summaryPrompt,
  SYSTEM_PROMPT,
  taskStateFile,
  type ParsedSummary,
} from './summary'

const edits = atom({ plugin: 'session-band', key: 'edits' } as const, 0)
const prompts = atom({ plugin: 'session-band', key: 'prompts' } as const, 0)

const REFUSED =
  'Clear refused: the transcript is already gone, nothing to summarise. Run save-session first, or re-run /clear.'
const CANCELLED = 'Clear cancelled: nothing was saved.'
const SAVE_FAILED = 'Clear cancelled: the save step failed.'

const reset = async ($: EngineInterface) => {
  await update($, edits, () => 0)
  await update($, prompts, () => 0)
}

const resolveRepo = async ($: EngineInterface): Promise<RepoInfo> => {
  const out = await $.process.run(['git', 'rev-parse', '--path-format=absolute', '--show-toplevel', '--git-common-dir'])
  const [top, common] = out.stdout.trim().split('\n')

  if (out.exitCode !== 0 || !top || !common) return {}

  const taskId = (await $.fs.read(`${top}/.agent-task-id`).catch(() => '')).trim() || undefined

  return toRepoInfo(common, taskId)
}

const sessionsDir = async ($: EngineInterface): Promise<string | undefined> => {
  const out = await $.process.run(['agent-session', 'path'])
  return out.exitCode === 0 && out.stdout.trim() !== '' ? out.stdout.trim() : undefined
}

// A save in the last five minutes counts as "already saved by hand": the task
// state file's mtime in a task worktree, else the newest file in the sessions
// directory. (The non-task statePath is .claude/session-state.md, which the CLI
// maintains, so it is not the signal here.)
const recentlySaved = async ($: EngineInterface, repo: RepoInfo, nowMs: number): Promise<boolean> => {
  if (repo.taskId !== undefined && repo.statePath !== undefined) {
    const stat = await $.fs.stat(repo.statePath).catch(() => undefined)
    return stat !== undefined && nowMs - stat.mtimeMs <= RECENT_SAVE_MS
  }

  const dir = await sessionsDir($)
  if (dir === undefined) return false

  const entries = await $.fs.list(dir).catch(() => undefined)
  if (entries === undefined) return false

  let newest: number | undefined
  for (const entry of entries) {
    // Only session files count; index.json is rewritten by any save, by any harness.
    if (entry.kind === 'file' && entry.name.endsWith('.md') && (newest === undefined || entry.mtimeMs > newest)) {
      newest = entry.mtimeMs
    }
  }

  return newest !== undefined && nowMs - newest <= RECENT_SAVE_MS
}

const saveSession = async ($: EngineInterface, repo: RepoInfo, summary: ParsedSummary): Promise<string> => {
  // Task worktrees write the claimed state file; the orchestrator goes through
  // the agent-session CLI, which resolves the sessions directory itself.
  if (repo.statePath !== undefined && repo.taskId !== undefined) {
    await $.fs.write(repo.statePath, taskStateFile(repo.taskId, summary.body))
    return repo.statePath
  }

  const root = await $.session.root()
  const saved = await $.process.run(
    ['agent-session', 'save', '--harness', 'cc', '--goal', summary.goal, '--stdin'],
    { cwd: root, stdin: summary.body, timeoutMs: 30_000 },
  )
  if (saved.exitCode !== 0) throw new Error(`agent-session exit ${saved.exitCode}`)

  const path = extractSavedPath(saved.stdout)
  if (path !== undefined) return path

  const active = await $.process.run(['agent-session', 'active'])
  if (active.exitCode === 0 && active.stdout.trim() !== '') return active.stdout.trim()

  throw new Error('agent-session printed no path')
}

const fail = async (
  $: EngineInterface,
  e: CommandRunInput,
  next: Next<'command.run'>,
  reason: string,
): Promise<CommandRunResult> => {
  // A plugin or headless run has nobody to answer; refuse rather than hang.
  if (e.origin.kind !== 'composer') return { text: CANCELLED }

  try {
    const answer = await $.ui.ask(`Save failed (${reason}). Clear anyway?`, ['Clear anyway', 'Cancel'])
    if (answer === 'Clear anyway') {
      await reset($)
      return next(e)
    }
    return { text: CANCELLED }
  } catch {
    return { text: CANCELLED }
  }
}

export const register: Register = on => {
  // The module's own counters: real work is a successful edit tool or enough
  // prompts. The transcript may already be wiped by the time /clear runs.
  on('prompt.submit', async ($, e, next) => {
    await update($, prompts, n => n + 1)
    return next(e)
  })

  on('tool.call', { tool: ['Edit', 'Write', 'MultiEdit', 'NotebookEdit'] }, async ($, e, next) => {
    const result = await next(e)
    if (!('deny' in result)) {
      await update($, edits, n => n + 1)
    }
    return result
  })

  on('command.run', { command: 'clear' }, async ($, e, next) => {
    const [editCount, promptCount] = await Promise.all([read($, edits), read($, prompts)])
    if (!isRealWork({ edits: editCount, prompts: promptCount })) {
      await reset($)
      return next(e)
    }

    const repo = await resolveRepo($)
    const nowMs = await $.clock.now()
    if (await recentlySaved($, repo, nowMs)) {
      await reset($)
      return next(e)
    }

    const messages = await $.session.messages()
    if (messages.length === 0) {
      // Counters say work happened but the transcript is gone: refuse, and do
      // not reset, so a later save + /clear still reaches the recent-save skip.
      return { text: REFUSED }
    }

    const reply = await $.model.complete({
      model: 'sonnet',
      system: SYSTEM_PROMPT,
      prompt: summaryPrompt(buildDigest(messages)),
      maxTokens: 2000,
      effort: 'low',
      timeoutMs: 60_000,
    })

    const summary = reply.isAnswered ? parseReply(reply.text) : undefined
    if (summary === undefined) {
      return fail($, e, next, reply.isAnswered ? 'the summary was not parseable' : `model ${reply.reason}`)
    }

    try {
      const path = await saveSession($, repo, summary)
      await reset($)
      // The answer's text, not a toast: /clear ends the session and the toast went with it.
      const result = await next(e)
      return { ...result, text: `Session saved: ${path}` }
    } catch (error) {
      return fail($, e, next, String(error))
    }
  }).catch(($, e, next) => next.called ? next(e) : { text: SAVE_FAILED })
}

