import { atom, read, update, type CommandRunInput, type CommandRunResult, type EngineInterface, type Register } from 'claude-code'

import { acceptsOrigin, disable, enable, hasSendItBlock, isEligible, isOn, refusedRepos, SEND_IT_SINCE, sendItOn } from './send-it'

const LOG = '.claude/state/send-it.log'
const SETTINGS = '.claude/settings.local.json'
const CONFLICT_PREFIX = 'send-it: refused, these keys already hold other values:'
const RULE = '.claude/rules/send-it.md'
const MISSING_RULE = 'send-it is on but ~/.claude/rules/send-it.md is missing or unreadable; the mode runs without its rules.'
const REFUSED_CHANGE = 'send-it: this settings change is refused mid-session and applies at the next session start.'

// True while send-it runs in this session. Set at session start, read by the rule and the ConfigChange guard.
const sendItAtom = atom({ plugin: 'session-band', key: 'sendIt' } as const, false)

// Reads the repo's local settings as loaded and records whether send-it runs in this session.
export async function refreshSendIt($: EngineInterface): Promise<boolean> {
  const on = sendItOn(await $.settings.read({ source: 'local' }))
  await update($, sendItAtom, () => on)
  return on
}

// The local settings as they are on disk now: a mid-session edit is visible here, not in the loaded settings.
const onDiskLocalText = async ($: EngineInterface): Promise<string> => {
  const top = (await git($, ['rev-parse', '--show-toplevel'])).split('\n')[0] ?? ''
  return top ? $.fs.read(`${top}/${SETTINGS}`).catch(() => '') : ''
}

const git = async ($: EngineInterface, args: string[]): Promise<string> => {
  const r = await $.process.run(['git', ...args]).catch(() => undefined)
  return r?.exitCode === 0 ? r.stdout.trim() : ''
}

// Appends one line. A failed read skips the write, so an unreadable log is never overwritten.
const appendLog = async ($: EngineInterface, home: string, line: string) => {
  const path = `${home}/${LOG}`
  try {
    const prior = (await $.fs.exists(path)) ? await $.fs.read(path) : ''
    await $.fs.write(path, `${prior}${line}\n`)
  } catch { /* logging must not block the command */ }
}

const reply = async ($: EngineInterface, home: string, args: string, repo: string, result: string): Promise<CommandRunResult> => {
  await appendLog($, home, `${new Date(await $.clock.now()).toISOString()} /send-it ${args} ${repo} ${result}`)
  return { text: result }
}

const handle = async ($: EngineInterface, e: CommandRunInput): Promise<CommandRunResult> => {
  if (!acceptsOrigin(e.origin.kind)) return { text: 'send-it: refused, only the person can run /send-it at the composer' }
  const args = e.args.trim()
  if (!['on', 'off', 'status'].includes(args)) return { text: 'send-it: usage /send-it on|off|status' }
  const home = await $.env.get('HOME')
  if (!home) return { text: 'send-it: HOME is unset, not editing anything' }

  const [top, common] = (await git($, ['rev-parse', '--path-format=absolute', '--show-toplevel', '--git-common-dir'])).split('\n')
  if (!top || !common) return { text: 'send-it: not inside a git repo' }
  const root = (await git($, ['rev-list', '--max-parents=0', 'HEAD'])).split('\n')[0] ?? ''
  const rootDate = root ? await git($, ['show', '-s', '--format=%cI', root]) : ''

  if (!isEligible(common, rootDate, home)) {
    const why = refusedRepos(home).includes(common)
      ? 'this repo is on the refused list'
      : `its root commit is before ${SEND_IT_SINCE} or unreadable`
    return reply($, home, args, common, `send-it: refused, ${why}`)
  }

  const path = `${top}/${SETTINGS}`
  try {
    const text = (await $.fs.exists(path)) ? await $.fs.read(path) : '{}'
    if (args === 'status') return reply($, home, args, common, `send-it is ${isOn(text) ? 'on' : 'off'} for this repo`)
    await $.fs.write(path, args === 'on' ? enable(text) : disable(text))
  } catch (err) {
    // Only the conflict refusal is shown as-is: it names key paths, never values.
    // Any other error keeps the fixed text, since parse errors can quote the file.
    const msg = err instanceof Error ? err.message : ''
    if (msg.startsWith(CONFLICT_PREFIX)) return reply($, home, args, common, msg)
    return reply($, home, args, common, `send-it: ${SETTINGS} could not be read as a JSON object; not editing it`)
  }
  return reply($, home, args, common, 'written; restart to apply')
}

export const register: Register = on => {
  on('command.run', { command: 'send-it' }, async ($, e, _next) => handle($, e))

  // Settings changes are refused while send-it runs or its block sits in the repo; they apply at the next start.
  on('classic.ConfigChange', async ($, e, next) => {
    if (e.source !== 'local_settings' && e.source !== 'user_settings') return next(e)
    const guarded = await read($, sendItAtom) || hasSendItBlock(await onDiskLocalText($))
    return guarded ? { block: REFUSED_CHANGE } : next(e)
  })

  // The rule is injected only while send-it is on. Refreshing here too keeps it right whichever start hook runs first.
  on('classic.SessionStart', async ($, e, next) => {
    const result = await next(e)
    if (!(await refreshSendIt($))) return result
    const home = await $.env.get('HOME')
    const text = home ? await $.fs.read(`${home}/${RULE}`).catch(() => undefined) : undefined
    if (text === undefined) {
      $.ui.toast(MISSING_RULE, { timeoutMs: 15_000 })
      return { ...result, additionalContext: [...(result.additionalContext ?? []), MISSING_RULE] }
    }
    return { ...result, additionalContext: [...(result.additionalContext ?? []), text] }
  })
}

files.hooks/worktree-pane.tsx:
import { atom, read, update, type EngineInterface, type Register } from 'claude-code'

import type { WorktreeBranch, WorktreeRow, WorktreeState } from '../types'
import { nextPane } from './pane-nav'
import { countChanges, liveByTree, paneLines, parseAheadBehind, parseHeartbeat, parseWorktrees, treeKeys, type Worktree } from './worktrees'

const view = atom({ plugin: 'session-band', key: 'worktrees' } as const, { open: false, legend: true } as WorktreeState)
// Same key as send-it.tsx, which sets it at session start; the state scan needs the atom declared in each file that reads it.
const sendItAtom = atom({ plugin: 'session-band', key: 'sendIt' } as const, false)

const FRESH_MS = 60_000

// Read-only git: a failing call (no upstream, not a repo) yields undefined rather than an error.
const git = async ($: EngineInterface, cwd: string, args: string[]): Promise<string | undefined> => {
  const r = await $.process.run(['git', '-C', cwd, '--no-optional-locks', ...args]).catch(() => undefined)
  return r && r.exitCode === 0 ? r.stdout : undefined
}

// A session's heartbeat names its cwd; a worktree has a live session when a fresh cwd sits inside its path.
const liveCwds = async ($: EngineInterface): Promise<string[]> => {
  const tmp = await $.env.get('TMPDIR') ?? '/tmp'
  const entries = await $.fs.list(tmp).catch(() => [])
  const now = await $.clock.now()
  const beats = entries.filter(entry => entry.kind === 'file' && entry.name.startsWith('session-band-') && entry.name.endsWith('.alive') && now - entry.mtimeMs < FRESH_MS)
  const bodies = await Promise.all(beats.map(entry => $.fs.read(`${tmp}/${entry.name}`).catch(() => '')))
  return bodies.flatMap(body => { const beat = parseHeartbeat(typeof body === 'string' ? body : ''); return beat ? [beat.cwd] : [] })
}

export const gather = async ($: EngineInterface, cwd: string): Promise<WorktreeState['data']> => {
  const trees: Worktree[] = parseWorktrees((await git($, cwd, ['worktree', 'list', '--porcelain'])) ?? '')
  const cwds = await liveCwds($)
  const liveByPath = liveByTree(cwds, trees.map(tree => tree.path))
  const rows: WorktreeRow[] = await Promise.all(trees.map(async tree => {
    const changes = countChanges((await git($, tree.path, ['status', '--porcelain'])) ?? '')
    const ab = await git($, tree.path, ['rev-list', '--left-right', '--count', '@{u}...HEAD'])
    const { ahead, behind } = ab ? parseAheadBehind(ab) : { ahead: 0, behind: 0 }
    const live = liveByPath.get(tree.path) ?? 0
    return { ...tree, changes, ahead, behind, live }
  }))
  const refs = (await git($, cwd, ['for-each-ref', '--format=%(refname:short)\t%(upstream:short)\t%(worktreepath)', 'refs/heads'])) ?? ''
  // A branch with no worktree has no row, so its ahead and behind come from its own upstream here.
  const branches: WorktreeBranch[] = await Promise.all(refs.split('\n').filter(Boolean).map(async line => {
    const [name = '', upstream = '', worktree = ''] = line.split('\t')
    const branch: WorktreeBranch = { name, upstream: upstream || undefined, worktree: worktree || undefined }
    if (branch.worktree || !branch.upstream) return branch
    const ab = await git($, cwd, ['rev-list', '--left-right', '--count', `${name}@{u}...${name}`])
    return { ...branch, ...(ab ? parseAheadBehind(ab) : {}) }
  }))
  return { rows, branches, at: await $.clock.now() }
}

const refresh = async ($: EngineInterface) => {
  const data = await gather($, await $.session.cwd())
  await update($, view, state => ({ ...state, data }))
}

// j/k move through the root and the tree items in display order; wraps at both ends.
const move = async ($: EngineInterface, step: 1 | -1) => {
  const state = await read($, view)
  const keys = treeKeys(state.data?.rows ?? [], state.data?.branches ?? [])
  if (keys.length === 0) return
  const at = Math.max(keys.indexOf(state.selected ?? keys[0]), 0)
  await update($, view, value => ({ ...value, selected: keys[(at + step + keys.length) % keys.length] }))
}

export const register: Register = on => {
  on('command.run', { command: 'worktrees' }, async ($, _e, _next) => {
    await $.ui.open({ id: 'worktrees', title: 'Worktrees', focus: true })
    return { text: 'Worktrees opened.' }
  })

  on('ui.open', { id: 'worktrees' }, async ($, e, next) => {
    const result = await next(e)
    await update($, view, state => ({ ...state, open: true }))
    await refresh($)
    return result
  })

  on('ui.close', { id: 'worktrees' }, async ($, e, next) => {
    const result = await next(e)
    if (!('deny' in result)) await update($, view, state => ({ ...state, open: false }))
    return result
  })

  on('ui.render', { component: 'Pane', requestId: 'worktrees' }, async ($, e, _next) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const state = await read($, view)
    const rows = state.data?.rows ?? []
    const branches = state.data?.branches ?? []
    const selectedKey = state.selected ?? treeKeys(rows, branches)[0]
    const sendIt = await read($, sendItAtom)
    const lines = paneLines(rows, branches, state.legend, selectedKey, sendIt)
    return <Box flexDirection="column">
      <Text weight="bold">Worktrees</Text>
      {/* Hotkeys, not hints: a key the pane does not bind falls through to the composer. */}
      <Box flexDirection="row" flexWrap="wrap" columnGap={2} marginBottom={1}>
        <Button key="wt-key-down" plain dimColor hotkey="j" label="down" onPress={() => void move($, 1)} />
        <Button key="wt-key-up" plain dimColor hotkey="k" label="up" onPress={() => void move($, -1)} />
        <Button key="wt-key-legend" plain dimColor hotkey="h" label="legend" onPress={() => void update($, view, value => ({ ...value, legend: !value.legend }))} />
        <Button key="wt-key-refresh" plain dimColor hotkey="r" label="refresh" onPress={() => void refresh($)} />
        <Button key="wt-key-prev" plain dimColor hotkey="b" label="prev pane" onPress={() => void $.ui.panes().then(panes => { const to = nextPane(panes.map(pane => pane.id), 'worktrees', -1); if (to && to !== 'worktrees') void $.ui.open({ id: to, focus: true }) })} />
        <Button key="wt-key-next" plain dimColor hotkey="f" label="next pane" onPress={() => void $.ui.panes().then(panes => { const to = nextPane(panes.map(pane => pane.id), 'worktrees', 1); if (to && to !== 'worktrees') void $.ui.open({ id: to, focus: true }) })} />
        <Button key="wt-key-quit" plain dimColor hotkey="q" label="close" onPress={() => void $.ui.close({ id: 'worktrees' })} />
      </Box>
      {lines.map((line, index) => <Text key={`wt-line-${index}`} mono color={line.color} weight={line.strong ? 'bold' : undefined}>{line.text}</Text>)}
    </Box>
  })
}

files.hooks/handoff.ts:
import type { PiProgress } from './pisession'
import { parsePiCommand, type PueueState, type Task } from './pueue'
import type { ReviewState } from './review'

export type TrackedTask = {
  id: number
  sessionId?: string
  runId?: string
  label?: string
  cwd: string
  addedMs: number
  task?: Task
  finishedMs?: number
  dismissed?: boolean
}

export type MonitorRow = {
  id: number
  state: PueueState
  glyph: string
  modelEffort?: string
  elapsed: string
  activity: string
  tokens: string
  cost: string
  idle?: { text: string; tone: 'muted' | 'yellow' | 'red' }
  label?: string
}

export type HandoffSegment = {
  kind: 'single' | 'rollup'
  text: string
  id?: number
  state?: PueueState
  glyph?: string
  model?: string
  effort?: string
  elapsed?: string
  tokens?: string
  cost?: string
  files?: number
  label?: string
  review?: ReviewState
  exit?: number
  running?: number
  done?: number
}

const finished = (state: PueueState | undefined) => state === 'Done' || state === 'Failed' || state === 'Killed'
const live = (state: PueueState | undefined) => state === 'Queued' || state === 'Running' || state === 'Paused'
const glyph = (state: PueueState | undefined) => state === 'Running' ? '▶' : state === 'Queued' ? '…' : state === 'Paused' ? 'Ⅱ' : state === 'Done' ? '✓' : state === 'Failed' || state === 'Killed' ? '!' : '?'
const cost = (value: number) => `$${value < 0.01 ? value.toFixed(3) : value.toFixed(2)}`
// The band and monitor deliberately use different glyphs for queued, paused, and failed tasks.
const monitorGlyph = (state: PueueState) => state === 'Running' ? '▶' : state === 'Queued' ? '◌' : state === 'Paused' ? '⏸' : state === 'Done' ? '✓' : state === 'Failed' || state === 'Killed' ? '✗' : '?'
const linger = (item: TrackedTask, nowMs: number) =>
  nowMs - (item.finishedMs ?? item.task?.endMs ?? item.addedMs) <= 30_000
const monitorVisible = (item: TrackedTask, nowMs: number) => {
  const state = item.task?.state
  return !item.dismissed && (live(state) || state === 'Failed' || state === 'Killed' || (state === 'Done' && linger(item, nowMs)))
}
const monitorOrder = (state: PueueState) => state === 'Failed' || state === 'Killed' ? 0 : state === 'Running' ? 1 : state === 'Queued' || state === 'Paused' ? 2 : state === 'Done' ? 3 : 4

export const formatElapsed = (ms: number): string => {
  const seconds = Math.max(0, Math.floor(ms / 1000))
  if (seconds < 60) return `${seconds}s`
  const minutes = Math.floor(seconds / 60)
  return minutes < 60 ? `${minutes}m${seconds % 60}s` : `${Math.floor(minutes / 60)}h${minutes % 60}m`
}

/** One line for the desktop notification when a tracked hand-off leaves the live states. */
export const finishNotice = (item: TrackedTask, pi: PiProgress | undefined): string => {
  const task = item.task
  const ran = task?.startMs !== undefined && task.endMs !== undefined ? formatElapsed(task.endMs - task.startMs) : undefined
  const label = item.label ? ` · ${item.label}` : ''
  if (task?.state === 'Done') return `pi#${item.id} Done${ran ? ` in ${ran}` : ''}${label}`
  if (task?.state === 'Failed') return `pi#${item.id} Failed (exit ${task.exit ?? '?'})${ran ? ` after ${ran}` : ''}${pi?.error ? `: ${pi.error}` : ''}${label}`
  return `pi#${item.id} ${task?.state ?? 'Finished'}${ran ? ` after ${ran}` : ''}${label}`
}

export const formatTokens = (tokens: number): string => tokens >= 1_000_000 ? `${(tokens / 1_000_000).toFixed(1)}m` : tokens >= 1000 ? `${(tokens / 1000).toFixed(1)}k` : String(tokens)

export const activityLabel = (progress: PiProgress | undefined): string =>
  progress?.lastActivity ?? (progress?.lastEventAssistant ? 'thinking' : 'starting')

export const idleAge = (progress: PiProgress | undefined, task: Task | undefined, nowMs: number): MonitorRow['idle'] => {
  if (!progress?.lastEventMs || finished(task?.state)) return undefined
  const age = nowMs - progress.lastEventMs
  if (age <= 30_000) return undefined
  return { text: `idle ${formatElapsed(age)}`, tone: age > 300_000 ? 'red' : age > 120_000 ? 'yellow' : 'muted' }
}

export const monitorRows = (
  tracked: readonly TrackedTask[],
  progress: Readonly<Record<number, PiProgress | undefined>>,
  tasks: readonly Task[],
  nowMs: number,
): MonitorRow[] => {
  const current = new Map(tasks.map(task => [task.id, task]))
  return tracked
    .map(item => ({ item, task: current.get(item.id) ?? item.task }))
    .filter(({ item, task }) => monitorVisible({ ...item, task }, nowMs))
    .sort((left, right) => {
      const stateOrder = monitorOrder(left.task?.state ?? 'Other') - monitorOrder(right.task?.state ?? 'Other')
      if (stateOrder !== 0) return stateOrder
      if (left.task?.state === 'Done' && right.task?.state === 'Done') return (right.task.endMs ?? right.item.finishedMs ?? right.item.addedMs) - (left.task.endMs ?? left.item.finishedMs ?? left.item.addedMs)
      return 0
    })
    .map(({ item, task }) => {
      const state = task?.state ?? 'Other'
      const pi = progress[item.id]
      const parsed = task ? parsePiCommand(task.command) : undefined
      const started = task?.startMs ?? task?.enqueuedMs ?? item.addedMs
      const ended = finished(state) ? task?.endMs ?? nowMs : nowMs
      const modelEffort = item.sessionId ? [pi?.model ?? parsed?.model, pi?.effort ?? parsed?.effort].filter(Boolean).join(':') || undefined : undefined
      const idle = idleAge(pi, task, nowMs)
      return {
        id: item.id,
        state,
        glyph: monitorGlyph(state),
        ...(modelEffort ? { modelEffort } : {}),
        elapsed: formatElapsed(ended - started),
        activity: item.sessionId ? activityLabel(pi) : 'n/a',
        tokens: pi ? `${formatTokens(pi.tokens)} tok` : 'n/a',
        cost: pi ? cost(pi.cost) : 'n/a',
        ...(idle ? { idle } : {}),
        ...(item.label ? { label: item.label } : {}),
      }
    })
}

const isReviewResult = (item: TrackedTask, review: ReviewState) =>
  item.task?.state === 'Failed' && item.task.exit === 1 && review !== undefined

const visible = (item: TrackedTask, review: ReviewState, nowMs: number) => {
  const state = item.task?.state
  if (live(state) || state === 'Killed' || (state === 'Failed' && !isReviewResult(item, review))) return true
  if (state !== 'Done' && !isReviewResult(item, review)) return false
  if (review === 'pending' || review === 'decided, waiting for the next Pi run in this repo') return true
  return linger(item, nowMs)
}

export const summarize = (
  tracked: readonly TrackedTask[],
  progress: Readonly<Record<number, PiProgress | undefined>>,
  review: Readonly<Record<number, ReviewState | undefined>>,
  nowMs: number,
): HandoffSegment | null => {
  const items = tracked.filter(item => !item.dismissed && visible(item, review[item.id], nowMs))
  if (items.length === 0) return null
  if (items.length > 1) {
    const active = items.filter(item => live(item.task?.state)).length
    const done = items.filter(item => item.task?.state === 'Done').length
    return { kind: 'rollup', text: `pi ${active}▶${done ? ` ${done}✓` : ''}`, running: active, done }
  }
  const item = items[0]!
  const task = item.task
  const pi = progress[item.id]
  const taskState = task?.state ?? 'Other'
  const state = isReviewResult(item, review[item.id]) ? 'Done' : taskState
  const parsed = task ? parsePiCommand(task.command) : undefined
  const model = pi?.model ?? parsed?.model
  const started = task?.startMs ?? task?.enqueuedMs ?? item.addedMs
  const elapsed = formatElapsed((finished(taskState) ? task?.endMs ?? nowMs : nowMs) - started)
  const modelEffort = [model, pi?.effort ?? parsed?.effort].filter(Boolean).join(':') || undefined
  const fields = [
    `pi#${item.id}${glyph(state)}`,
    modelEffort,
    elapsed,
    pi ? `${formatTokens(pi.tokens)} tok` : item.sessionId ? 'n/a' : 'n/a',
    pi && pi.cost > 0 ? cost(pi.cost) : undefined,
    pi?.files.length ? `${pi.files.length} files` : undefined,
    item.label,
    review[item.id],
    state === 'Failed' && task?.exit !== undefined ? `exit ${task.exit}` : undefined,
    state === 'Killed' ? 'killed' : undefined,
  ].filter(Boolean)
  return {
    kind: 'single', text: fields.join(' '), id: item.id, state, glyph: glyph(state),
    ...(model ? { model } : {}), ...(pi?.effort ?? parsed?.effort ? { effort: pi?.effort ?? parsed?.effort } : {}), elapsed,
    ...(pi ? { tokens: formatTokens(pi.tokens), cost: cost(pi.cost), files: pi.files.length } : {}),
    ...(item.label ? { label: item.label } : {}), ...(review[item.id] ? { review: review[item.id] } : {}), ...(task?.exit !== undefined ? { exit: task.exit } : {}),
  }
}

export type StaleSession = { path: string; name: string; mtimeMs: number; size: number }
export type StaleSelection = { tasks: TrackedTask[]; sessions: StaleSession[]; bytes: number }

export const selectStale = (tracked: readonly TrackedTask[], sessions: readonly StaleSession[], nowMs: number): StaleSelection => {
  const older = nowMs - 7 * 24 * 60 * 60 * 1000
  const tasks = tracked.filter(item => finished(item.task?.state) && (item.task?.endMs ?? item.finishedMs ?? item.addedMs) < older)
  const labels = new Set(tasks.flatMap(item => item.sessionId?.startsWith('pueue-') ? [item.sessionId] : []))
  const selected = sessions.filter(session => session.mtimeMs < older && [...labels].some(id => session.name.endsWith(`_${id}.jsonl`)))
  return { tasks, sessions: selected, bytes: selected.reduce((total, session) => total + session.size, 0) }
}

files.hooks/pisession.ts:
export type TranscriptEntry = { kind: 'text' | 'tool' | 'error'; text: string }

export type PiProgress = {
  offset: number
  partial: string
  tokens: number
  cost: number
  model?: string
  effort?: string
  lastActivity?: string
  lastEventMs?: number
  lastEventAssistant?: boolean
  files: string[]
  entries: TranscriptEntry[]
  error?: string
  models: Record<string, number>
}

export const emptyProgress = (): PiProgress => ({
  offset: 0,
  partial: '',
  tokens: 0,
  cost: 0,
  files: [],
  entries: [],
  models: {},
})

export const sessionDir = (cwd: string): string => `--${cwd.replace(/^\/+/, '').replaceAll('/', '-')}--`
export const sessionFileName = (id: string): RegExp => new RegExp(`_(${id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})\\.jsonl$`)

const object = (value: unknown): Record<string, unknown> | undefined =>
  value !== null && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : undefined

const strings = (value: unknown): string[] => Array.isArray(value) ? value.filter((item): item is string => typeof item === 'string') : []

const toolPath = (arguments_: unknown): string | undefined => {
  const args = object(arguments_)
  return ['path', 'file_path', 'filePath'].map(key => args?.[key]).find((value): value is string => typeof value === 'string')
}

const entry = (kind: TranscriptEntry['kind'], text: string): TranscriptEntry | undefined => text.trim() ? { kind, text: text.trim() } : undefined

const append = (progress: PiProgress, entries: TranscriptEntry[]) => ({ ...progress, entries: [...progress.entries, ...entries].slice(-200) })

const event = (progress: PiProgress, raw: unknown): PiProgress => {
  const row = object(raw)
  if (!row) return progress
  const message = row.type === 'message' ? object(row.message) : undefined
  const parsedTimestamp = typeof row.timestamp === 'string' ? Date.parse(row.timestamp) : Number.NaN
  const dated = Number.isNaN(parsedTimestamp) || (progress.lastEventMs !== undefined && parsedTimestamp <= progress.lastEventMs)
    ? progress
    : { ...progress, lastEventMs: parsedTimestamp, lastEventAssistant: message ? message.role === 'assistant' : progress.lastEventAssistant }
  if (row.type === 'model_change') {
    const provider = typeof row.provider === 'string' ? row.provider : undefined
    const modelId = typeof row.modelId === 'string' ? row.modelId : undefined
    return provider && modelId ? { ...dated, model: `${provider}/${modelId}` } : dated
  }
  if (row.type === 'thinking_level_change' && typeof row.thinkingLevel === 'string') return { ...dated, effort: row.thinkingLevel }
  if (row.type !== 'message') return dated
  if (!message) return dated
  const role = message.role
  const content = Array.isArray(message.content) ? message.content : []
  let next = dated
  if (role === 'assistant') {
    const usage = object(message.usage)
    const tokens = typeof usage?.totalTokens === 'number' ? usage.totalTokens : 0
    const cost = typeof object(usage?.cost)?.total === 'number' ? Number(object(usage?.cost)?.total) : 0
    const model = typeof message.model === 'string' && typeof message.provider === 'string' ? `${message.provider}/${message.model}` : next.model
    const key = model ?? 'unknown'
    next = { ...next, tokens: next.tokens + tokens, cost: next.cost + cost, model, models: { ...next.models, [key]: (next.models[key] ?? 0) + cost } }
    const entries: TranscriptEntry[] = []
    const files = new Set(next.files)
    for (const block of content) {
      const item = object(block)
      if (item?.type === 'text' && typeof item.text === 'string') { const value = entry('text', item.text); if (value) entries.push(value) }
      if (item?.type === 'toolCall') {
        const name = typeof item.name === 'string' ? item.name : 'tool'
        const path = toolPath(item.arguments)
        if (path) files.add(path)
        const args = object(item.arguments)
        const command = typeof args?.command === 'string' ? args.command : undefined
        const text = name === 'bash' && command ? `bash ${command.replace(/\s+/g, ' ').trim().slice(0, 40)}` : `${name}${path ? ` ${path}` : ''}`
        entries.push({ kind: 'tool', text })
        next = { ...next, lastActivity: text }
      }
    }
    next = { ...next, files: [...files] }
    if (message.stopReason === 'error' || typeof message.errorMessage === 'string') {
      const error = typeof message.errorMessage === 'string' && message.errorMessage.trim() ? message.errorMessage.trim() : 'Pi stopped with an error'
      next = { ...next, error, lastActivity: 'error' }
      // Pi retries a failed request; the same error repeated is one transcript line.
      const last = next.entries.at(-1)
      if (last?.kind !== 'error' || last.text !== error) entries.push({ kind: 'error', text: error })
    }
    return append(next, entries)
  }
  if (role === 'toolResult') {
    const text = strings(content.map(object).map(block => block?.text)).join(' ')
    return message.isError === true ? append({ ...next, error: text || 'Tool failed' }, entry('error', text || 'Tool failed') ? [entry('error', text || 'Tool failed')!] : []) : next
  }
  return next
}

/** Fold a tail chunk without ever parsing an incomplete JSONL line. */
export const fold = (progress: PiProgress, chunk: string): PiProgress => {
  const combined = progress.partial + chunk
  const lines = combined.split('\n')
  const partial = lines.pop() ?? ''
  let next = { ...progress, offset: progress.offset + new TextEncoder().encode(chunk).byteLength, partial }
  for (const line of lines) {
    try { next = event(next, JSON.parse(line)) } catch { /* opaque/corrupt events are ignored */ }
  }
  return next
}

