// Pure layout of the band's text: which runs show, in what order, and what a narrow band drops first.
// No engine here, so band.test.ts pins the exact strings; band.tsx only maps the runs to Text.
import type { GitSnapshot, Usage } from '../types'
import type { HandoffSegment } from './handoff'
import { ctxBar } from './format'
import { ctxTone, limitTone, type Tone } from './palette'
import { SYMBOL } from './worktrees'

/** One coloured run. `drop` ranks what a narrow band gives up, 1 first; a run without it always stays. */
export type Seg = { text: string; tone: Tone; drop?: number }

/** Between groups. Runs inside a group are joined by one space. */
export const SEP = ' · '

export type StatusInput = { dir: string; model: string; usage: Usage; git: GitSnapshot | null; style: string | null; openAlerts?: number; sendIt?: boolean }

/** Left to right: where (dir, branch, sync), budget (ctx, 5h, 7d), alerts, who (model, style). */
export const statusGroups = (d: StatusInput): Seg[][] => {
  const g = d.git
  const where: Seg[] = [{ text: d.dir, tone: 'peach' }]
  if (g) {
    where.push({ text: `${g.branch}${g.isDirty ? '*' : ''}`, tone: g.isDirty ? 'yellow' : 'green' })
    if (!g.hasUpstream) where.push({ text: 'local', tone: 'muted', drop: 3 })
    if (g.ahead > 0) where.push({ text: `${SYMBOL.ahead}${g.ahead}`, tone: 'green' })
    if (g.behind > 0) where.push({ text: `${SYMBOL.behind}${g.behind}`, tone: 'yellow' })
    if (g.stash > 0) where.push({ text: `${SYMBOL.stash}${g.stash}`, tone: 'peach', drop: 4 })
  }
  const u = d.usage
  const budget: Seg[] = []
  if (u.ctx !== undefined) budget.push({ text: ctxBar(u.ctx), tone: ctxTone(u.ctx) })
  if (u.five !== undefined) budget.push({ text: `5h:${u.five}%`, tone: limitTone(u.five) })
  if (u.seven !== undefined) budget.push({ text: `7d:${u.seven}%`, tone: limitTone(u.seven) })
  const alerts: Seg[] = d.openAlerts ? [{ text: `⚠${d.openAlerts}`, tone: 'red' }] : []
  // No drop rank: fitStatus never removes it, so the send-it state stays visible at any width.
  if (d.sendIt) alerts.push({ text: '⇉ send-it', tone: 'red' })
  const who: Seg[] = [{ text: d.model, tone: 'mauve' }]
  if (d.style) who.push({ text: d.style, tone: 'muted', drop: 1 })
  return [where, budget, alerts, who].filter(group => group.length > 0)
}

export const statusText = (groups: readonly Seg[][]): string =>
  groups.map(group => group.map(seg => seg.text).join(' ')).join(SEP)

/** Drops runs by rank until the line fits `width`; anything still too wide the Text truncates at its end. */
export const fitStatus = (groups: Seg[][], width: number): Seg[][] => {
  let kept = groups
  for (const rank of [1, 3, 4]) {
    if (statusText(kept).length <= width) break
    kept = kept.map(group => group.filter(seg => seg.drop !== rank)).filter(group => group.length > 0)
  }
  return kept
}

/** Keep the identity, model and outcome first when a narrow terminal needs truncation. */
export const handoffText = (handoff: HandoffSegment, width?: number): string => {
  if (handoff.kind === 'rollup') return handoff.text
  const required = [`pi#${handoff.id}${handoff.glyph ?? ''}`, [handoff.model, handoff.effort].filter(Boolean).join(':') || undefined, handoff.review, handoff.exit === undefined ? undefined : `exit ${handoff.exit}`].filter(Boolean)
  const optional = [handoff.elapsed, handoff.tokens && `${handoff.tokens} tok`, handoff.cost, handoff.files ? `${handoff.files} files` : undefined, handoff.label].filter(Boolean)
  const full = [...required.slice(0, 2), ...optional, ...required.slice(2)].join(' ')
  if (width === undefined || full.length <= width) return full
  const withoutLabelFilesTokensCost = [...required.slice(0, 2), handoff.elapsed, ...required.slice(2)].filter(Boolean).join(' ')
  if (withoutLabelFilesTokensCost.length <= width) return withoutLabelFilesTokensCost
  return [...required.slice(0, 2), ...required.slice(2)].filter(Boolean).join(' ')
}

// The terminal draws a Button as `[ label ]`: four cells of chrome, then one cell of gap to its neighbour.
const CHIP = 5

export type BandInput = StatusInput & { handoff?: HandoffSegment; width?: number; wt: boolean }
export type BandLayout = { wt?: string; status: Seg[][]; pi?: string }

/** The status line gets the room first, less the Pi chip's shortest form; the Pi chip gets what is left. */
export const layoutBand = (d: BandInput): BandLayout => {
  const wt = d.wt ? 'wt' : undefined
  const groups = statusGroups(d)
  if (d.width === undefined) return { wt, status: groups, pi: d.handoff && handoffText(d.handoff) }
  const wtCells = wt ? wt.length + CHIP : 0
  const piFloor = d.handoff ? handoffText(d.handoff, 0).length + CHIP : 0
  const status = fitStatus(groups, d.width - wtCells - piFloor)
  const pi = d.handoff && handoffText(d.handoff, d.width - wtCells - statusText(status).length - CHIP)
  return { wt, status, pi }
}

files.hooks/classify.ts:
export type Tier = 'pass' | 'ask' | 'deny'

type Separator = ';' | '&&' | '||' | '|' | '&' | '\n'

type Word = {
  value: string
  dynamic: boolean
  // The word embeds a quoted-heredoc substitution, replaced by a literal placeholder.
  heredoc?: true
}

export type CommandFact = {
  command: string
  program?: string
  args: string[]
  targets: string[]
}

export type Classification = {
  tier: Tier
  reason?: string
  commands: CommandFact[]
}

type Segment = {
  words: Word[]
  separator?: Separator
}

type Tokenized = {
  segments: Segment[]
  cannotAnalyze?: boolean
}

const SYSTEM_DIRECTORY = /^\/(?:usr|etc|bin|System|Users)\/?$/
const SHELL = new Set(['sh', 'bash', 'zsh'])
const TIER_ORDER: Record<Tier, number> = { pass: 0, ask: 1, deny: 2 }

const basename = (value: string) => value.split('/').filter(Boolean).at(-1) ?? value

const isAssignment = (value: string) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(value)

const hasRecursiveFlag = (args: readonly string[]) => args.some(arg => arg === '--recursive' || /^-[^-]*[rR]/.test(arg))

const hasForceFlag = (args: readonly string[]) => args.some(arg => arg === '--force' || arg === '--force-with-lease' || /^-[^-]*f/.test(arg))

const nonOptions = (args: readonly string[]) => {
  const values: string[] = []
  let afterDoubleDash = false
  for (const arg of args) {
    if (arg === '--') {
      afterDoubleDash = true
      continue
    }
    if (afterDoubleDash || !arg.startsWith('-') || arg === '-') values.push(arg)
  }
  return values
}

const stripLauncher = (words: readonly Word[]): Word[] => {
  let remaining = [...words]

  while (remaining.length > 0) {
    while (remaining[0] && isAssignment(remaining[0].value)) remaining = remaining.slice(1)
    const launcher = basename(remaining[0]?.value ?? '')

    if (launcher === 'rtk') {
      remaining = remaining.slice(1)
      if (remaining[0]?.value === 'proxy') remaining = remaining.slice(1)
      continue
    }

    if (launcher === 'command' || launcher === 'builtin' || launcher === 'exec' || launcher === 'nohup' || launcher === 'time') {
      remaining = remaining.slice(1)
      while (remaining[0]?.value.startsWith('-')) remaining = remaining.slice(1)
      continue
    }

    if (launcher === 'env') {
      remaining = remaining.slice(1)
      while (remaining[0] && (remaining[0].value.startsWith('-') || isAssignment(remaining[0].value))) remaining = remaining.slice(1)
      continue
    }

    if (launcher === 'sudo') {
      remaining = remaining.slice(1)
      while (remaining[0]?.value.startsWith('-')) {
        const option = remaining[0].value
        remaining = remaining.slice(1)
        if (['-u', '-g', '-h', '-C', '--user', '--group', '--host', '--chdir', '--close-from', '--prompt', '--role', '--type'].includes(option)) {
          remaining = remaining.slice(1)
        }
      }
      continue
    }

    if (launcher === 'xargs') {
      remaining = remaining.slice(1)
      while (remaining[0]?.value.startsWith('-')) {
        const option = remaining[0].value
        remaining = remaining.slice(1)
        if (['-a', '-d', '-E', '-e', '-I', '-i', '-L', '-l', '-n', '-P', '-s', '--arg-file', '--delimiter', '--eof', '--replace', '--max-lines', '--max-args', '--max-procs', '--max-chars'].includes(option)) {
          remaining = remaining.slice(1)
        }
      }
      continue
    }

    break
  }

  return remaining
}

const WHOLE_TREE = new Set(['/', '/*', '~', '~/', '~/*', '$HOME', '$HOME/', '$HOME/*'])

const isAbsoluteOrHome = (target: string) =>
  target.startsWith('/') || target === '~' || target.startsWith('~/') || target === '$HOME' || target.startsWith('$HOME/')

// Deny the whole tree or a top-level system directory itself. Anything below
// them is a question, unless it is the old hook's `rm -rf <absolute or home>`.
const isDangerousRmTarget = (target: string, recursiveAndForce: boolean) =>
  WHOLE_TREE.has(target) || SYSTEM_DIRECTORY.test(target) || (recursiveAndForce && isAbsoluteOrHome(target))

const isMainRef = (value: string) => {
  const destination = value.replace(/^\+/, '').split(':').at(-1) ?? ''
  const branch = destination.replace(/^refs\/heads\//, '')

  return branch === 'main' || branch === 'master'
}

const isShell = (program: string | undefined) => program !== undefined && SHELL.has(program)

// `$(cat <<'TAG' ... TAG)` with a quoted tag expands nothing: the body is literal text.
// Returns how many characters it spans, or undefined when it is anything else, including a
// body holding a line equal to the tag (the shell would end the heredoc there and run the rest).
const HEREDOC = /^\$\(cat <<'(\w+)'\n([\s\S]*?)\n\1[ \t]*\n?[ \t]*\)/

const literalHeredoc = (rest: string): number | undefined => {
  const match = HEREDOC.exec(rest)
  if (!match) return undefined

  return (match[2] ?? '').split('\n').includes(match[1] ?? '') ? undefined : match[0].length
}

// Only a commit, tag or note message, or a gh pr/issue/release body, may carry one: anywhere
// else the text could be run (`bash -c`, `python -c`, `git rebase --exec`).
const takesLiteralHeredoc = (program: string | undefined, args: readonly string[]) =>
  (program === 'git' && ['commit', 'tag', 'notes'].includes(args[0] ?? '')) ||
  (program === 'gh' && ['pr', 'issue', 'release'].includes(args[0] ?? ''))

const containsOverwrite = (args: readonly string[]) => args.some((arg, index) => {
  if (arg !== '>' && arg !== '>>') return false
  const target = args[index + 1]
  return target !== '/dev/null' && !/^&\d+$/.test(target ?? '')
})

const factFor = (segment: Segment): CommandFact => {
  const normalized = stripLauncher(segment.words)
  const program = normalized[0] ? basename(normalized[0].value) : undefined
  const args = normalized.slice(1).map(word => word.value)
  const values = nonOptions(args)
  let targets: string[] = []

  if (program === 'rm' || program === 'chmod' || program === 'find') targets = values
  if (program === 'mv') targets = values.slice(-1)
  if (program === 'git' && ['clean', 'checkout', 'restore'].includes(args[0] ?? '')) targets = values.slice(1)
  if (containsOverwrite(args)) {
    targets.push(...args.flatMap((arg, index) => {
      const target = args[index + 1]
      return (arg === '>' || arg === '>>') && target !== undefined && target !== '/dev/null' && !/^&\d+$/.test(target) ? [target] : []
    }))
  }

  return { command: segment.words.map(word => word.value).join(' '), program, args, targets }
}

const classifySegment = (segment: Segment): Classification => {
  const fact = factFor(segment)
  const { program, args } = fact
  const values = nonOptions(args)

  if (segment.words.some(word => word.heredoc) && !takesLiteralHeredoc(program, args)) {
    return { tier: 'ask', reason: "can't analyze a heredoc outside a git message or gh body", commands: [fact] }
  }
  if (containsOverwrite(args)) return { tier: 'ask', reason: 'overwriting a redirect', commands: [fact] }
  if (program === 'eval') return { tier: 'ask', reason: "can't analyze eval", commands: [fact] }
  if (isShell(program) && (args.includes('<<') || args.includes('<<-'))) return { tier: 'ask', reason: "can't analyze a here-doc feeding a shell", commands: [fact] }
  if (segment.separator === '|' && isShell(program)) return { tier: 'ask', reason: "can't analyze a pipe into a shell", commands: [fact] }
  if (isShell(program) && args.includes('-c')) {
    const body = args[args.indexOf('-c') + 1]
    const word = stripLauncher(segment.words).at(args.indexOf('-c') + 2)
    if (!body || word?.dynamic) return { tier: 'ask', reason: "can't analyze a dynamic shell body", commands: [fact] }
  }

  if (program === 'rm') {
    const recursiveAndForce = hasRecursiveFlag(args) && hasForceFlag(args)
    if (values.some(target => isDangerousRmTarget(target, recursiveAndForce))) {
      return { tier: 'deny', reason: 'rm targets a root, home, or system path', commands: [fact] }
    }
    return { tier: 'ask', reason: 'rm deletes files', commands: [fact] }
  }

  if (program === 'git') {
    const subcommand = args[0]
    // `+ref` forces by refspec without any flag; `HEAD:main` names main as the destination.
    const refs = values.slice(1)
    if (subcommand === 'push' && (hasForceFlag(args) || refs.some(ref => ref.startsWith('+'))) && refs.some(isMainRef)) {
      return { tier: 'deny', reason: 'force-push targets main or master', commands: [fact] }
    }
    if (subcommand === 'reset' && args.includes('--hard')) {
      const ref = values.slice(1).at(-1)
      if (ref?.startsWith('origin/') || ref === '@{u}') return { tier: 'deny', reason: 'hard reset targets a remote upstream ref', commands: [fact] }
      return { tier: 'ask', reason: 'git reset --hard discards work', commands: [fact] }
    }
    if (subcommand === 'clean') return { tier: 'ask', reason: 'git clean deletes files', commands: [fact] }
    if ((subcommand === 'checkout' || subcommand === 'restore') && values.slice(1).includes('.')) return { tier: 'ask', reason: `git ${subcommand} . discards work`, commands: [fact] }
    if (subcommand === 'stash' && ['drop', 'clear'].includes(args[1] ?? '')) return { tier: 'ask', reason: `git stash ${args[1]} discards work`, commands: [fact] }
  }

  if (program === 'mv') return { tier: 'ask', reason: 'mv may overwrite its destination', commands: [fact] }
  if (program === 'find' && args.includes('-delete')) return { tier: 'ask', reason: 'find -delete removes files', commands: [fact] }
  if (program === 'chmod' && hasRecursiveFlag(args)) return { tier: 'ask', reason: 'chmod -R changes permissions recursively', commands: [fact] }
  if ((program === 'docker' || program === 'kubectl') && args.some(arg => ['rm', 'rmi', 'prune', 'delete', 'kill'].includes(arg))) {
    return { tier: 'ask', reason: `${program} deletes resources`, commands: [fact] }
  }

  return { tier: 'pass', commands: [fact] }
}

export const tokenize = (command: string): Tokenized => {
  const segments: Segment[] = []
  let words: Word[] = []
  let word = ''
  let dynamic = false
  let heredoc = false
  let quote: 'single' | 'double' | undefined
  let separator: Separator | undefined
  let cannotAnalyze = false

  const pushWord = () => {
    if (word) words.push(heredoc ? { value: word, dynamic, heredoc: true } : { value: word, dynamic })
    word = ''
    dynamic = false
    heredoc = false
  }
  const pushSegment = (nextSeparator: Separator) => {
    pushWord()
    if (words.length > 0) segments.push({ words, separator })
    words = []
    separator = nextSeparator
  }

  for (let index = 0; index < command.length; index += 1) {
    const char = command[index] ?? ''
    const next = command[index + 1]

    if (char === '\\' && quote !== 'single') {
      if (next === undefined) {
        cannotAnalyze = true
      } else {
        word += next
        index += 1
      }
      continue
    }

    if (char === "'" && quote !== 'double') {
      quote = quote === 'single' ? undefined : 'single'
      continue
    }
    if (char === '"' && quote !== 'single') {
      quote = quote === 'double' ? undefined : 'double'
      continue
    }

    if (quote !== 'single' && char === '$' && next === '(') {
      const length = literalHeredoc(command.slice(index))
      if (length) {
        word += '<heredoc>'
        heredoc = true
        index += length - 1
        continue
      }
    }

    if (quote !== 'single' && char === '`') cannotAnalyze = true
    if (quote !== 'single' && char === '$') {
      dynamic = true
      if (next === '(') cannotAnalyze = true
    }

    if (quote) {
      word += char
      continue
    }

    if (char === '>' || (char === '<' && next === '<')) {
      pushWord()
      if (char === '<') {
        words.push({ value: next === '<' && command[index + 2] === '-' ? '<<-' : '<<', dynamic: false })
        index += next === '<' && command[index + 2] === '-' ? 2 : 1
      } else {
        words.push({ value: next === '>' ? '>>' : '>', dynamic: false })
        if (next === '>') index += 1
        if (command[index + 1] === '&') {
          let target = '&'
          index += 1
          while (/\d/.test(command[index + 1] ?? '')) {
            target += command[index + 1]
            index += 1
          }
          words.push({ value: target, dynamic: false })
        }
      }
      continue
    }

    if (/\s/.test(char)) {
      if (char === '\n') pushSegment('\n')
      else pushWord()
      continue
    }

    if (char === ';') {
      pushSegment(';')
      continue
    }
    if (char === '|' || char === '&') {
      const joined = next === char ? `${char}${char}` as Separator : char as Separator
      pushSegment(joined)
      if (next === char) index += 1
      continue
    }

    word += char
  }

  pushWord()
  if (words.length > 0) segments.push({ words, separator })
  if (quote) cannotAnalyze = true

  return { segments, cannotAnalyze }
}

export const classify = (command: string): Classification => {
  const parsed = tokenize(command)
  if (parsed.cannotAnalyze) return { tier: 'ask', reason: "can't analyze this command", commands: parsed.segments.map(factFor) }

  return parsed.segments.reduce<Classification>((strictest, segment) => {
    const candidate = classifySegment(segment)
    if (TIER_ORDER[candidate.tier] > TIER_ORDER[strictest.tier]) return {
      ...candidate,
      commands: [...strictest.commands, ...candidate.commands],
    }
    return { ...strictest, commands: [...strictest.commands, ...candidate.commands] }
  }, { tier: 'pass', commands: [] })
}

